package com.yuyutian.mytools.media.library.repository;
import com.yuyutian.mytools.media.library.model.MediaModels.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
import java.sql.Timestamp;import java.time.Instant;import java.util.*;
/** Media Library 仓储。 */ @Repository public class MediaRepository {
 private final JdbcTemplate jdbc; /** 创建仓储。 @param jdbc JDBC */ public MediaRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 /** 检查或登记事件。 @param eventId 事件 @param hash 摘要 @param now 时间 @return 是否为新事件 */ public boolean acceptEvent(String eventId,String hash,Instant now){List<String> existing=jdbc.query("SELECT payload_sha256 FROM media_event_inbox WHERE event_id=?",(rs,row)->rs.getString(1),eventId);if(!existing.isEmpty()){if(!existing.getFirst().equals(hash))throw new IllegalStateException("media event idempotency conflict");return false;}jdbc.update("INSERT INTO media_event_inbox VALUES (?,'AssetRegistered',?,?)",eventId,hash,Timestamp.from(now));return true;}
 /** 合并资产事件。 @param event 事件 @param now 时间 @return 媒体 */ public MediaView merge(AssetEvent event,Instant now){String directoryId=null;if(event.directoryKey()!=null&&!event.directoryKey().isBlank()){directoryId=jdbc.query("SELECT id FROM media_directory WHERE owner_id=? AND external_key=?",(rs,row)->rs.getString(1),event.ownerId(),event.directoryKey()).stream().findFirst().orElse(null);if(directoryId==null){directoryId=UUID.randomUUID().toString();jdbc.update("INSERT INTO media_directory(id,owner_id,parent_id,external_key,name,created_at,updated_at) VALUES (?,?,NULL,?,?,?,?)",directoryId,event.ownerId(),event.directoryKey(),event.directoryName()==null?event.directoryKey():event.directoryName(),Timestamp.from(now),Timestamp.from(now));}}
  if(event.scanId()!=null){Integer valid=jdbc.queryForObject("SELECT COUNT(*) FROM media_scan_entry e JOIN media_scan s ON s.id=e.scan_id JOIN media_directory d ON d.id=s.directory_id WHERE e.scan_id=? AND e.source_business_id=? AND e.content_sha256=? AND e.size_bytes=? AND e.mime_type=? AND s.owner_id=? AND s.status='STAGING' AND d.external_key=?",Integer.class,event.scanId().toString(),event.sourceBusinessId(),event.contentSha256().toLowerCase(),event.sizeBytes(),event.mimeType(),event.ownerId(),event.directoryKey());if(valid==null||valid!=1)throw new IllegalStateException("media scan event does not match staged entry");}
  List<String> sourceAsset=jdbc.query("SELECT i.asset_id FROM media_item_source s JOIN media_item i ON i.id=s.media_item_id WHERE s.owner_id=? AND s.source_type=? AND s.source_business_id=?",(rs,row)->rs.getString(1),event.ownerId(),event.sourceType(),event.sourceBusinessId());if(!sourceAsset.isEmpty()&&!sourceAsset.getFirst().equals(event.assetId().toString()))throw new IllegalStateException("media source identity conflict");
  List<UUID> ids=jdbc.query("SELECT id FROM media_item WHERE owner_id=? AND asset_id=?",(rs,row)->UUID.fromString(rs.getString(1)),event.ownerId(),event.assetId().toString());UUID id;
  if(ids.isEmpty()){id=UUID.randomUUID();jdbc.update("INSERT INTO media_item (id,owner_id,asset_id,directory_id,source_type,source_business_id,display_name,mime_type,size_bytes,content_sha256,status,version,created_at,updated_at,last_seen_scan_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id.toString(),event.ownerId(),event.assetId().toString(),directoryId,event.sourceType(),event.sourceBusinessId(),event.displayName(),event.mimeType(),event.sizeBytes(),event.contentSha256().toLowerCase(),"READY",1L,Timestamp.from(now),Timestamp.from(now),event.scanId()==null?null:event.scanId().toString());}
  else{id=ids.getFirst();jdbc.update("UPDATE media_item SET directory_id=?,display_name=?,mime_type=?,size_bytes=?,content_sha256=?,status='READY',last_seen_scan_id=?,version=version+1,updated_at=? WHERE id=?",directoryId,event.displayName(),event.mimeType(),event.sizeBytes(),event.contentSha256().toLowerCase(),event.scanId()==null?null:event.scanId().toString(),Timestamp.from(now),id.toString());}
  if(sourceAsset.isEmpty())jdbc.update("INSERT INTO media_item_source VALUES (?,?,?,?,?,?,?)",id.toString(),event.ownerId(),event.sourceType(),event.sourceBusinessId(),event.displayName(),Timestamp.from(now),Timestamp.from(now));else jdbc.update("UPDATE media_item_source SET display_name=?,updated_at=? WHERE owner_id=? AND source_type=? AND source_business_id=?",event.displayName(),Timestamp.from(now),event.ownerId(),event.sourceType(),event.sourceBusinessId());
  if(event.scanId()!=null){int updated=jdbc.update("UPDATE media_scan_entry SET status='IMPORTED',media_item_id=?,imported_at=? WHERE scan_id=? AND source_business_id=? AND status IN ('STAGED','IMPORTED')",id.toString(),Timestamp.from(now),event.scanId().toString(),event.sourceBusinessId());if(updated!=1)throw new IllegalStateException("media scan entry is not staged");List<String> relation=jdbc.query("SELECT media_item_id FROM media_directory_entry WHERE directory_id=? AND source_business_id=?",(rs,row)->rs.getString(1),directoryId,event.sourceBusinessId());if(relation.isEmpty())jdbc.update("INSERT INTO media_directory_entry VALUES (?,?,?,'READY',?,?,?)",directoryId,event.sourceBusinessId(),id.toString(),event.scanId().toString(),Timestamp.from(now),Timestamp.from(now));else{if(!relation.getFirst().equals(id.toString()))throw new IllegalStateException("media directory entry identity conflict");jdbc.update("UPDATE media_directory_entry SET status='READY',last_seen_scan_id=?,updated_at=? WHERE directory_id=? AND source_business_id=?",event.scanId().toString(),Timestamp.from(now),directoryId,event.sourceBusinessId());}}
  bumpRevision(now);return view(id).orElseThrow();}
 /** 合并旧迁移来源的标签关系。 @param itemId 媒体 @param ownerId 所有者 @param sourceType 来源类型 @param sourceBusinessId 来源标识 @param tags 标签 @param now 时间 */ public void mergeLegacyTags(UUID itemId,long ownerId,String sourceType,String sourceBusinessId,List<TagInput>tags,Instant now){for(TagInput input:tags){String name=input.name().trim().toLowerCase(Locale.ROOT);String tagId=jdbc.query("SELECT id FROM media_tag WHERE owner_id=? AND name=?",(rs,row)->rs.getString(1),ownerId,name).stream().findFirst().orElse(null);if(tagId==null){tagId=UUID.randomUUID().toString();jdbc.update("INSERT INTO media_tag VALUES (?,?,?,?)",tagId,ownerId,name,Timestamp.from(now));}Integer sourceTagCount=jdbc.queryForObject("SELECT COUNT(*) FROM media_item_source_tag WHERE owner_id=? AND source_type=? AND source_business_id=? AND tag_id=?",Integer.class,ownerId,sourceType,sourceBusinessId,tagId);if(sourceTagCount!=null&&sourceTagCount==0)jdbc.update("INSERT INTO media_item_source_tag VALUES (?,?,?,?,?,?,?)",itemId.toString(),ownerId,sourceType,sourceBusinessId,tagId,input.confidence(),Timestamp.from(now));else jdbc.update("UPDATE media_item_source_tag SET confidence=? WHERE owner_id=? AND source_type=? AND source_business_id=? AND tag_id=?",input.confidence(),ownerId,sourceType,sourceBusinessId,tagId);Integer relationCount=jdbc.queryForObject("SELECT COUNT(*) FROM media_tag_relation WHERE media_item_id=? AND tag_id=? AND source='LEGACY_MIGRATION'",Integer.class,itemId.toString(),tagId);if(relationCount!=null&&relationCount==0)jdbc.update("INSERT INTO media_tag_relation VALUES (?,?,?,?,NULL,?)",itemId.toString(),tagId,"LEGACY_MIGRATION",input.confidence(),Timestamp.from(now));else jdbc.update("UPDATE media_tag_relation SET confidence=CASE WHEN confidence IS NULL OR confidence<? THEN ? ELSE confidence END WHERE media_item_id=? AND tag_id=? AND source='LEGACY_MIGRATION'",input.confidence(),input.confidence(),itemId.toString(),tagId);}}
 /** 记录本次旧媒体迁移证据。 @param request 请求 @param payloadSha256 载荷摘要 @param itemId 媒体 @param now 时间 */ public void recordLegacyMigration(LegacyMediaImport request,String payloadSha256,UUID itemId,Instant now){List<LegacyMigrationRecord> existing=jdbc.query("SELECT migration_key,source_snapshot_id,source_system,legacy_asset_id,payload_sha256,media_item_id,tag_count FROM legacy_media_migration WHERE source_system=? AND legacy_asset_id=?",(rs,row)->new LegacyMigrationRecord(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),UUID.fromString(rs.getString(6)),rs.getInt(7)),request.sourceSystem(),request.legacyAssetId());if(!existing.isEmpty()){LegacyMigrationRecord value=existing.getFirst();if(!value.migrationKey().equals(request.migrationKey())||!value.sourceSnapshotId().equals(request.sourceSnapshotId())||!value.payloadSha256().equals(payloadSha256)||!value.mediaItemId().equals(itemId)||value.tagCount()!=request.tags().size())throw new IllegalStateException("legacy media migration identity conflict");return;}jdbc.update("INSERT INTO legacy_media_migration VALUES (?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),request.migrationKey(),request.sourceSnapshotId(),request.sourceSystem(),request.legacyAssetId(),payloadSha256,itemId.toString(),request.tags().size(),Timestamp.from(now));}
 /** 读取指定迁移键的稳定目标证据。 @param migrationKey 迁移键 @return 迁移记录 */ public List<LegacyMigrationRecord> legacyMigrationRecords(String migrationKey){return jdbc.query("SELECT migration_key,source_snapshot_id,source_system,legacy_asset_id,payload_sha256,media_item_id,tag_count FROM legacy_media_migration WHERE migration_key=? ORDER BY source_system,legacy_asset_id",(rs,row)->new LegacyMigrationRecord(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),UUID.fromString(rs.getString(6)),rs.getInt(7)),migrationKey);}
/** 回填旧媒体真实目录。 @param binding 目录绑定 @param now 时间 */ public void bindLegacyDirectory(LegacyDirectoryBinding binding,Instant now){String parentId=ensureDirectory(binding.ownerId(),binding.parentDirectoryKey(),binding.parentDirectoryName(),null,now);String directoryId=ensureDirectory(binding.ownerId(),binding.directoryKey(),binding.directoryName(),parentId,now);int updated=jdbc.update("UPDATE media_item SET directory_id=?,updated_at=? WHERE owner_id=? AND EXISTS (SELECT 1 FROM media_item_source s WHERE s.media_item_id=media_item.id AND s.owner_id=? AND s.source_type='LEGACY_ASSET' AND s.source_business_id=?)",directoryId,Timestamp.from(now),binding.ownerId(),binding.ownerId(),"local_file:"+binding.legacyAssetId());if(updated!=1)throw new IllegalArgumentException("legacy media directory target not found");}
 /** 查询媒体。 @param id 标识 @return 媒体 */ public Optional<MediaView> view(UUID id){return jdbc.query("SELECT i.*,d.external_key AS directory_key,d.name AS directory_name FROM media_item i LEFT JOIN media_directory d ON d.id=i.directory_id WHERE i.id=?",(rs,row)->new MediaView(UUID.fromString(rs.getString("id")),rs.getLong("owner_id"),UUID.fromString(rs.getString("asset_id")),rs.getString("display_name"),rs.getString("mime_type"),rs.getLong("size_bytes"),rs.getString("content_sha256"),rs.getString("status"),rs.getLong("version"),tags(UUID.fromString(rs.getString("id"))),rs.getString("directory_key"),rs.getString("directory_name")),id.toString()).stream().findFirst();}
 /** 分页查询所有者媒体。 @param ownerId 所有者 @param afterId 起始标识 @param includeMissing 是否包含缺失项 @param mimePrefix MIME 前缀 @param limit 数量 @return 媒体 */ public List<MediaView> list(long ownerId,UUID afterId,boolean includeMissing,String mimePrefix,int limit){StringBuilder sql=new StringBuilder("SELECT id FROM media_item WHERE owner_id=?");List<Object> arguments=new ArrayList<>();arguments.add(ownerId);if(afterId!=null){sql.append(" AND id>?");arguments.add(afterId.toString());}if(!includeMissing)sql.append(" AND status<>'MISSING'");if(mimePrefix!=null&&!mimePrefix.isBlank()){sql.append(" AND mime_type LIKE ?");arguments.add(mimePrefix+"%");}sql.append(" ORDER BY id LIMIT ?");arguments.add(limit);return jdbc.query(sql.toString(),(rs,row)->UUID.fromString(rs.getString(1)),arguments.toArray()).stream().map(id->view(id).orElseThrow()).toList();}
 /** 同步查询媒体目录，不经过任务调度。 @param ownerId 所有者 @param mimePrefix MIME前缀 @param tag 标签 @param keyword 关键字 @param excludeAdult 是否排除成人内容 @param offset 偏移 @param limit 数量 @return 媒体 */
 public List<MediaView> catalog(long ownerId,String mimePrefix,String directoryId,String tag,String keyword,boolean excludeAdult,int offset,int limit){
  QueryParts query=catalogQuery(ownerId,mimePrefix,directoryId,tag,keyword,excludeAdult);
  String sql="SELECT i.id "+query.from()+query.where()+" ORDER BY i.updated_at DESC,i.id LIMIT ? OFFSET ?";
  List<Object> arguments=new ArrayList<>(query.arguments());arguments.add(limit);arguments.add(offset);
  return jdbc.query(sql,(rs,row)->UUID.fromString(rs.getString(1)),arguments.toArray()).stream()
   .map(id->view(id).orElseThrow()).toList();
 }
 /** 统计同步媒体目录数量。 @param ownerId 所有者 @param mimePrefix MIME前缀 @param tag 标签 @param keyword 关键字 @param excludeAdult 是否排除成人内容 @return 数量 */
 public long catalogCount(long ownerId,String mimePrefix,String directoryId,String tag,String keyword,boolean excludeAdult){
  QueryParts query=catalogQuery(ownerId,mimePrefix,directoryId,tag,keyword,excludeAdult);
  Long count=jdbc.queryForObject("SELECT COUNT(*) "+query.from()+query.where(),Long.class,query.arguments().toArray());
  return count==null?0L:count;
 }
 /** 聚合可用标签。 @param ownerId 所有者 @param mimePrefix MIME前缀 @param keyword 关键字 @param excludeAdult 是否排除成人内容 @return 标签计数 */
 public List<MediaTagCount> catalogTags(long ownerId,String mimePrefix,String keyword,boolean excludeAdult){
  QueryParts query=catalogQuery(ownerId,mimePrefix,"","",keyword,excludeAdult);
  String sql="SELECT t.name,COUNT(DISTINCT i.id) "+query.from()+
   " JOIN media_tag_relation ctr ON ctr.media_item_id=i.id JOIN media_tag t ON t.id=ctr.tag_id"+
   query.where()+" GROUP BY t.name ORDER BY COUNT(DISTINCT i.id) DESC,t.name LIMIT 500";
  return jdbc.query(sql,(rs,row)->new MediaTagCount(rs.getString(1),rs.getLong(2)),query.arguments().toArray());
 }
 /** 聚合真实媒体目录。 @param ownerId 所有者 @param mimePrefix MIME前缀 @param keyword 关键字 @param excludeAdult 是否排除成人内容 @return 目录计数 */
 public List<MediaDirectoryCount> catalogDirectories(long ownerId,String mimePrefix,String keyword,boolean excludeAdult){
  QueryParts query=catalogQuery(ownerId,mimePrefix,"","",keyword,excludeAdult);
  String sql="SELECT d.external_key,d.name,COUNT(DISTINCT i.id),p.external_key,p.name "+query.from()+
   " JOIN media_directory d ON d.id=i.directory_id LEFT JOIN media_directory p ON p.id=d.parent_id"+query.where()+
   " GROUP BY d.external_key,d.name,p.external_key,p.name ORDER BY p.name,d.name,d.external_key";
  return jdbc.query(sql,(rs,row)->new MediaDirectoryCount(rs.getString(1),rs.getString(2),rs.getLong(3),rs.getString(4),rs.getString(5)),query.arguments().toArray());
 }
 private QueryParts catalogQuery(long ownerId,String mimePrefix,String directoryId,String tag,String keyword,boolean excludeAdult){
  StringBuilder where=new StringBuilder(" WHERE i.owner_id=? AND i.status<>'MISSING' AND i.mime_type LIKE ?");
  List<Object> arguments=new ArrayList<>();arguments.add(ownerId);arguments.add(mimePrefix+"%");
  if(directoryId!=null&&!directoryId.isBlank()){where.append(" AND EXISTS (SELECT 1 FROM media_directory cd WHERE cd.id=i.directory_id AND cd.external_key=?)");arguments.add(directoryId);}
  if(tag!=null&&!tag.isBlank()){where.append(" AND EXISTS (SELECT 1 FROM media_tag_relation sr JOIN media_tag st ON st.id=sr.tag_id WHERE sr.media_item_id=i.id AND st.name=?)");arguments.add(tag.trim().toLowerCase(Locale.ROOT));}
  if(keyword!=null&&!keyword.isBlank()){where.append(" AND (LOWER(i.display_name) LIKE ? OR EXISTS (SELECT 1 FROM media_tag_relation kr JOIN media_tag kt ON kt.id=kr.tag_id WHERE kr.media_item_id=i.id AND LOWER(kt.name) LIKE ?))");String pattern="%"+keyword.trim().toLowerCase(Locale.ROOT)+"%";arguments.add(pattern);arguments.add(pattern);}
  if(excludeAdult)where.append(" AND NOT EXISTS (SELECT 1 FROM media_tag_relation ar JOIN media_tag at ON at.id=ar.tag_id WHERE ar.media_item_id=i.id AND at.name='r18')");
  return new QueryParts("FROM media_item i",where.toString(),arguments);
 }
 /** 解析旧文件标识。 @param ownerId 所有者 @param itemId 媒体标识 @return 旧文件标识 */ public Optional<Long> legacyFileId(long ownerId,UUID itemId){return jdbc.query("SELECT s.source_business_id FROM media_item_source s JOIN media_item i ON i.id=s.media_item_id WHERE i.id=? AND i.owner_id=? AND s.source_type='LEGACY_ASSET'",(rs,row)->rs.getString(1),itemId.toString(),ownerId).stream().filter(value->value.startsWith("local_file:")).map(value->Long.parseLong(value.substring(11))).findFirst();}
 /** 按旧文件标识查询媒体。 @param ownerId 所有者 @param legacyId 旧文件标识 @return 媒体 */ public Optional<MediaView> viewByLegacyFile(long ownerId,long legacyId){return jdbc.query("SELECT i.id FROM media_item_source s JOIN media_item i ON i.id=s.media_item_id WHERE s.owner_id=? AND s.source_type='LEGACY_ASSET' AND s.source_business_id=? AND i.status<>'MISSING'",(rs,row)->UUID.fromString(rs.getString(1)),ownerId,"local_file:"+legacyId).stream().findFirst().flatMap(this::view);}
 /** 查询最新缩略图资产。 @param ownerId 所有者 @param itemId 媒体标识 @return 缩略图资产 */ public Optional<UUID> latestThumbnailAsset(long ownerId,UUID itemId){return jdbc.query("SELECT a.asset_id FROM media_artifact a JOIN media_item i ON i.id=a.media_item_id WHERE a.media_item_id=? AND i.owner_id=? AND a.artifact_kind='THUMBNAIL' ORDER BY a.created_at DESC LIMIT 1",(rs,row)->UUID.fromString(rs.getString(1)),itemId.toString(),ownerId).stream().findFirst();}
 /** 按所有者和资产查询媒体。 @param ownerId 所有者 @param assetId 资产 @return 媒体 */ public Optional<MediaView> viewByAsset(long ownerId,UUID assetId){return jdbc.query("SELECT id FROM media_item WHERE owner_id=? AND asset_id=?",(rs,row)->UUID.fromString(rs.getString(1)),ownerId,assetId.toString()).stream().findFirst().flatMap(this::view);}
 /** 开始分析。 @param itemId 媒体 @param request 请求 @param now 时间 @return 分析 */ public AnalysisView begin(UUID itemId,BeginAnalysis request,Instant now){List<AnalysisView> existing=jdbc.query("SELECT * FROM media_analysis WHERE media_item_id=? AND analysis_version=?",(rs,row)->analysis(rs),itemId.toString(),request.analysisVersion());if(!existing.isEmpty()){AnalysisView value=existing.getFirst();if(!value.taskInstanceId().equals(request.taskInstanceId()))throw new IllegalStateException("media analysis version is already bound");return value;}UUID id=UUID.randomUUID();jdbc.update("INSERT INTO media_analysis VALUES (?,?,?,?,?,NULL,NULL,NULL,NULL,?,?)",id.toString(),itemId.toString(),request.analysisVersion(),request.taskInstanceId().toString(),"RUNNING",Timestamp.from(now),Timestamp.from(now));jdbc.update("INSERT INTO media_task_binding VALUES (?,?,?,?)",itemId.toString(),request.taskInstanceId().toString(),"ANALYSIS",Timestamp.from(now));jdbc.update("UPDATE media_item SET status='ANALYZING',version=version+1,updated_at=? WHERE id=?",Timestamp.from(now),itemId.toString());bumpRevision(now);return new AnalysisView(id,itemId,request.analysisVersion(),request.taskInstanceId(),"RUNNING");}
 /** 检查分析版本是否已经绑定。 @param itemId 媒体标识 @param analysisVersion 分析版本 @return 是否存在 */ public boolean analysisVersionExists(UUID itemId,String analysisVersion){Integer value=jdbc.queryForObject("SELECT COUNT(*) FROM media_analysis WHERE media_item_id=? AND analysis_version=?",Integer.class,itemId.toString(),analysisVersion);return value!=null&&value>0;}
 /** 完成分析并替换版本化派生数据。 @param itemId 媒体 @param request 请求 @param resultHash 结果摘要 @param now 时间 */ public void complete(UUID itemId,CompleteAnalysis request,String resultHash,Instant now){AnalysisRecord analysis=jdbc.query("SELECT * FROM media_analysis WHERE media_item_id=? AND task_instance_id=?",(rs,row)->new AnalysisRecord(UUID.fromString(rs.getString("id")),rs.getString("analysis_version"),rs.getString("status"),rs.getString("result_sha256")),itemId.toString(),request.taskInstanceId().toString()).stream().findFirst().orElseThrow(()->new IllegalArgumentException("media analysis binding not found"));if("SUCCEEDED".equals(analysis.status())){if(!resultHash.equals(analysis.resultHash()))throw new IllegalStateException("media analysis result conflict");return;}if(!"RUNNING".equals(analysis.status()))throw new IllegalStateException("media analysis is not running");
  jdbc.update("DELETE FROM media_tag_relation WHERE media_item_id=? AND source='ANALYSIS' AND analysis_version=?",itemId.toString(),analysis.version());for(TagInput input:request.tags()==null?List.<TagInput>of():request.tags()){String name=input.name().trim().toLowerCase(Locale.ROOT);String tagId=jdbc.query("SELECT id FROM media_tag WHERE owner_id=(SELECT owner_id FROM media_item WHERE id=?) AND name=?",(rs,row)->rs.getString(1),itemId.toString(),name).stream().findFirst().orElse(null);if(tagId==null){tagId=UUID.randomUUID().toString();jdbc.update("INSERT INTO media_tag SELECT ?,owner_id,?,? FROM media_item WHERE id=?",tagId,name,Timestamp.from(now),itemId.toString());}jdbc.update("INSERT INTO media_tag_relation VALUES (?,?,?,?,?,?)",itemId.toString(),tagId,"ANALYSIS",input.confidence(),analysis.version(),Timestamp.from(now));}
  for(ArtifactInput artifact:request.artifacts()==null?List.<ArtifactInput>of():request.artifacts()){List<String> existing=jdbc.query("SELECT asset_id FROM media_artifact WHERE media_item_id=? AND artifact_kind=? AND generator_version=?",(rs,row)->rs.getString(1),itemId.toString(),artifact.kind(),artifact.generatorVersion());if(existing.isEmpty())jdbc.update("INSERT INTO media_artifact VALUES (?,?,?,?,?,?)",UUID.randomUUID().toString(),itemId.toString(),artifact.assetId().toString(),artifact.kind(),artifact.generatorVersion(),Timestamp.from(now));else if(!existing.getFirst().equals(artifact.assetId().toString()))throw new IllegalStateException("media artifact version conflict");}
  jdbc.update("UPDATE media_analysis SET status='SUCCEEDED',result_sha256=?,summary=?,description=?,updated_at=? WHERE id=?",resultHash,request.summary(),request.description(),Timestamp.from(now),analysis.id().toString());jdbc.update("UPDATE media_item SET status='READY',version=version+1,updated_at=? WHERE id=?",Timestamp.from(now),itemId.toString());bumpRevision(now);}
 /** 标记分析终态失败。 @param itemId 媒体 @param request 请求 @param now 时间 */ public void fail(UUID itemId,FailAnalysis request,Instant now){List<TerminalRecord> records=jdbc.query("SELECT status,error_code FROM media_analysis WHERE media_item_id=? AND task_instance_id=?",(rs,row)->new TerminalRecord(rs.getString(1),rs.getString(2)),itemId.toString(),request.taskInstanceId().toString());if(records.isEmpty())return;TerminalRecord current=records.getFirst();if(request.status().equals(current.status())){if(!Objects.equals(request.errorCode(),current.errorCode()))throw new IllegalStateException("media analysis terminal result conflicts");return;}if(!"RUNNING".equals(current.status()))throw new IllegalStateException("media analysis terminal status conflicts");jdbc.update("UPDATE media_analysis SET status=?,error_code=?,updated_at=? WHERE media_item_id=? AND task_instance_id=? AND status='RUNNING'",request.status(),request.errorCode(),Timestamp.from(now),itemId.toString(),request.taskInstanceId().toString());jdbc.update("UPDATE media_item SET status='READY',version=version+1,updated_at=? WHERE id=?",Timestamp.from(now),itemId.toString());bumpRevision(now);}
 /** 写入乐观锁播放进度。 @param ownerId 所有者 @param itemId 媒体 @param request 请求 @param now 时间 @return 进度 */ public ProgressView progress(long ownerId,UUID itemId,ProgressRequest request,Instant now){MediaView media=view(itemId).orElseThrow();if(media.ownerId()!=ownerId)throw new IllegalArgumentException("media item not found");Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM playback_progress WHERE owner_id=? AND media_item_id=?",Integer.class,ownerId,itemId.toString());long revision;if(count!=null&&count==0){if(request.expectedRevision()!=0)throw new IllegalStateException("media progress version conflict");revision=1;jdbc.update("INSERT INTO playback_progress VALUES (?,?,?,?,?,?,?,?)",ownerId,itemId.toString(),request.positionMs(),request.durationMs(),request.completed(),revision,Timestamp.from(request.clientUpdatedAt()),Timestamp.from(now));}else{revision=request.expectedRevision()+1;int updated=jdbc.update("UPDATE playback_progress SET position_ms=?,duration_ms=?,completed=?,revision=?,client_updated_at=?,server_updated_at=? WHERE owner_id=? AND media_item_id=? AND revision=?",request.positionMs(),request.durationMs(),request.completed(),revision,Timestamp.from(request.clientUpdatedAt()),Timestamp.from(now),ownerId,itemId.toString(),request.expectedRevision());if(updated==0)throw new IllegalStateException("media progress version conflict");}bumpRevision(now);return progressView(ownerId,itemId);}
 /** 将当前所有者媒体标记为缺失并移出活动目录。 @param ownerId 所有者 @param itemId 媒体 @param now 时间 */ public void delete(long ownerId,UUID itemId,Instant now){MediaView current=view(itemId).orElseThrow(()->new IllegalArgumentException("media item not found"));if(current.ownerId()!=ownerId)throw new IllegalArgumentException("media item not found");if("MISSING".equals(current.status()))return;jdbc.update("UPDATE media_item SET status='MISSING',version=version+1,updated_at=? WHERE id=? AND owner_id=?",Timestamp.from(now),itemId.toString(),ownerId);jdbc.update("UPDATE media_directory_entry SET status='MISSING',updated_at=? WHERE media_item_id=? AND status<>'MISSING'",Timestamp.from(now),itemId.toString());bumpRevision(now);}
 /** 开始幂等扫描批次。 @param request 请求 @param now 时间 @return 扫描 */ public ScanView beginScan(BeginScan request,Instant now){List<ScanView> existing=jdbc.query("SELECT s.*,d.external_key FROM media_scan s JOIN media_directory d ON d.id=s.directory_id WHERE s.owner_id=? AND s.idempotency_key=?",(rs,row)->scan(rs),request.ownerId(),request.idempotencyKey());if(!existing.isEmpty()){ScanView value=existing.getFirst();Integer matches=jdbc.queryForObject("SELECT COUNT(*) FROM media_scan s JOIN media_directory d ON d.id=s.directory_id WHERE s.id=? AND s.expected_count=? AND s.root_fingerprint=? AND d.external_key=?",Integer.class,value.id().toString(),request.expectedCount(),request.rootFingerprint().toLowerCase(),request.directoryKey());if(matches==null||matches!=1)throw new IllegalStateException("media scan idempotency conflict");return value;}String directoryId=ensureDirectory(request.ownerId(),request.directoryKey(),request.directoryName(),null,now);UUID scanId=UUID.randomUUID();jdbc.update("INSERT INTO media_scan VALUES (?,?,?,?,?,'STAGING',?,0,NULL,?,NULL)",scanId.toString(),request.ownerId(),directoryId,request.idempotencyKey(),request.rootFingerprint().toLowerCase(),request.expectedCount(),Timestamp.from(now));bumpRevision(now);return scan(scanId).orElseThrow();}
 /** 暂存扫描清单。 @param scanId 扫描 @param entries 条目 @param now 时间 */ public void stageScan(UUID scanId,List<ScanEntry> entries,Instant now){requireStaging(scanId);boolean changed=false;for(ScanEntry entry:entries){List<String> hash=jdbc.query("SELECT content_sha256 FROM media_scan_entry WHERE scan_id=? AND source_business_id=?",(rs,row)->rs.getString(1),scanId.toString(),entry.sourceBusinessId());if(hash.isEmpty()){jdbc.update("INSERT INTO media_scan_entry VALUES (?,?,?,?,?,?,'STAGED',NULL,?,NULL)",scanId.toString(),entry.sourceBusinessId(),entry.displayName(),entry.mimeType(),entry.sizeBytes(),entry.contentSha256().toLowerCase(),Timestamp.from(now));changed=true;}else if(!hash.getFirst().equals(entry.contentSha256().toLowerCase()))throw new IllegalStateException("media scan entry idempotency conflict");}if(changed)bumpRevision(now);}
 /** 发布完成的扫描批次。 @param scanId 扫描 @param digest 清单摘要 @param now 时间 @return 扫描 */ public ScanView finishScan(UUID scanId,String digest,Instant now){ScanView scan=scan(scanId).orElseThrow(()->new IllegalArgumentException("media scan not found"));if("COMPLETED".equals(scan.status())){if(!digest.equals(scan.manifestSha256()))throw new IllegalStateException("media scan manifest conflict");return scan;}if(!"STAGING".equals(scan.status()))throw new IllegalStateException("media scan is not staging");Integer total=jdbc.queryForObject("SELECT COUNT(*) FROM media_scan_entry WHERE scan_id=?",Integer.class,scanId.toString());Integer imported=jdbc.queryForObject("SELECT COUNT(*) FROM media_scan_entry WHERE scan_id=? AND status='IMPORTED'",Integer.class,scanId.toString());if(total==null||imported==null||total!=scan.expectedCount()||!total.equals(imported))throw new IllegalStateException("media scan is incomplete");String directoryId=jdbc.queryForObject("SELECT directory_id FROM media_scan WHERE id=?",String.class,scanId.toString());jdbc.update("UPDATE media_directory_entry SET status='MISSING',updated_at=? WHERE directory_id=? AND status='READY' AND last_seen_scan_id<>?",Timestamp.from(now),directoryId,scanId.toString());jdbc.update("UPDATE media_item SET status='MISSING',version=version+1,updated_at=? WHERE source_type='MEDIA_SCAN' AND status='READY' AND NOT EXISTS (SELECT 1 FROM media_directory_entry d WHERE d.media_item_id=media_item.id AND d.status='READY')",Timestamp.from(now));jdbc.update("UPDATE media_scan SET status='COMPLETED',imported_count=?,manifest_sha256=?,completed_at=? WHERE id=? AND status='STAGING'",imported,digest.toLowerCase(),Timestamp.from(now),scanId.toString());bumpRevision(now);return scan(scanId).orElseThrow();}
 /** 查询扫描。 @param scanId 扫描 @return 扫描 */ public Optional<ScanView> scan(UUID scanId){return jdbc.query("SELECT s.*,d.external_key FROM media_scan s JOIN media_directory d ON d.id=s.directory_id WHERE s.id=?",(rs,row)->scan(rs),scanId.toString()).stream().findFirst();}
 /** 返回当前领域修订号。 @return 修订号 */ public long libraryRevision(){Long value=jdbc.queryForObject("SELECT revision FROM media_library_revision WHERE singleton_id=1",Long.class);return value==null?0:value;}
 /** 分页读取确定性媒体关系快照。 @param afterId 起始标识 @param limit 数量 @return 快照 */ public List<ReconciliationSnapshot> reconciliationPage(UUID afterId,int limit){String sql="SELECT * FROM media_item "+(afterId==null?"":"WHERE id>?")+" ORDER BY id LIMIT ?";List<ItemRecord> items=afterId==null?jdbc.query(sql,(rs,row)->item(rs),limit):jdbc.query(sql,(rs,row)->item(rs),afterId.toString(),limit);return items.stream().map(item->new ReconciliationSnapshot(item,analysisRelations(item.id()),tagRelations(item.id()),artifactRelations(item.id()),directoryRelations(item.id()),sourceRelations(item.id()),sourceTagRelations(item.id()))).toList();}
 /** 返回领域表数量。 @param table 表 @param status 状态 @return 数量 */ public int count(String table,String status){Set<String> allowed=Set.of("media_directory","media_scan");if(!allowed.contains(table))throw new IllegalArgumentException("media reconciliation table is invalid");String sql="SELECT COUNT(*) FROM "+table+(status==null?"":" WHERE status=?");Integer value=status==null?jdbc.queryForObject(sql,Integer.class):jdbc.queryForObject(sql,Integer.class,status);return value==null?0:value;}
 /** 按旧文件标识解析分析目标。 @param legacyId 旧文件标识 @return 分析目标 */ public Optional<LegacyAnalysisTarget> legacyAnalysisTarget(long legacyId){return jdbc.query("SELECT i.id,i.asset_id,i.owner_id,i.display_name,i.mime_type,i.size_bytes,i.content_sha256 FROM media_item_source s JOIN media_item i ON i.id=s.media_item_id WHERE s.source_type='LEGACY_ASSET' AND s.source_business_id=?",(rs,row)->new LegacyAnalysisTarget(UUID.fromString(rs.getString(1)),UUID.fromString(rs.getString(2)),rs.getLong(3),rs.getString(4),rs.getString(5),rs.getLong(6),rs.getString(7)),"local_file:"+legacyId).stream().findFirst();}
 /** 保存任务操作。 @param id 操作 @param ownerId 所有者 @param type 类型 @param key 幂等键 @param taskId 任务 @param requestDigest 请求摘要 @param now 时间 @return 操作 */ public OperationView saveOperation(UUID id,long ownerId,String type,String key,UUID taskId,String requestDigest,Instant now){OperationView existing=findOperation(ownerId,key).orElse(null);if(existing!=null){if(!existing.taskInstanceId().equals(taskId)||!existing.operationType().equals(type))throw new IllegalStateException("media operation idempotency conflict");return existing;}jdbc.update("INSERT INTO media_operation (id,owner_id,operation_type,idempotency_key,task_instance_id,status,created_at,updated_at,request_sha256) VALUES (?,?,?,?,?,'PENDING',?,?,?)",id.toString(),ownerId,type,key,taskId.toString(),Timestamp.from(now),Timestamp.from(now),requestDigest);return findOperation(id,ownerId).orElseThrow();}
 /** 按所有者和幂等键查询操作。 @param ownerId 所有者 @param key 幂等键 @return 操作 */ public Optional<OperationView> findOperation(long ownerId,String key){return jdbc.query("SELECT * FROM media_operation WHERE owner_id=? AND idempotency_key=?",(rs,row)->operation(rs),ownerId,key).stream().findFirst();}
 /** 查询操作创建请求摘要。 @param id 操作 @return 摘要 */ public Optional<String> operationRequestDigest(UUID id){return jdbc.query("SELECT request_sha256 FROM media_operation WHERE id=? AND request_sha256 IS NOT NULL",(rs,row)->rs.getString(1),id.toString()).stream().findFirst();}
 /** 查询所有者操作。 @param id 操作 @param ownerId 所有者 @return 操作 */ public Optional<OperationView> findOperation(UUID id,long ownerId){return jdbc.query("SELECT * FROM media_operation WHERE id=? AND owner_id=?",(rs,row)->operation(rs),id.toString(),ownerId).stream().findFirst();}
 /** 更新操作状态。 @param id 操作 @param status 状态 @param now 时间 @return 操作 */ public OperationView updateOperation(UUID id,String status,Instant now){jdbc.update("UPDATE media_operation SET status=?,updated_at=? WHERE id=?",status,Timestamp.from(now),id.toString());return jdbc.query("SELECT * FROM media_operation WHERE id=?",(rs,row)->operation(rs),id.toString()).getFirst();}
 private String ensureDirectory(long ownerId,String key,String name,String parentId,Instant now){String directoryId=jdbc.query("SELECT id FROM media_directory WHERE owner_id=? AND external_key=?",(rs,row)->rs.getString(1),ownerId,key).stream().findFirst().orElse(null);if(directoryId==null){directoryId=UUID.randomUUID().toString();jdbc.update("INSERT INTO media_directory(id,owner_id,parent_id,external_key,name,created_at,updated_at) VALUES (?,?,?,?,?,?,?)",directoryId,ownerId,parentId,key,name,Timestamp.from(now),Timestamp.from(now));}else jdbc.update("UPDATE media_directory SET parent_id=?,name=?,updated_at=? WHERE id=?",parentId,name,Timestamp.from(now),directoryId);return directoryId;}
 private void requireStaging(UUID scanId){ScanView scan=scan(scanId).orElseThrow(()->new IllegalArgumentException("media scan not found"));if(!"STAGING".equals(scan.status()))throw new IllegalStateException("media scan is not staging");}
 private ScanView scan(java.sql.ResultSet rs)throws java.sql.SQLException{return new ScanView(UUID.fromString(rs.getString("id")),rs.getLong("owner_id"),rs.getString("external_key"),rs.getString("status"),rs.getInt("expected_count"),rs.getInt("imported_count"),rs.getString("manifest_sha256"));}
 private OperationView operation(java.sql.ResultSet rs)throws java.sql.SQLException{return new OperationView(UUID.fromString(rs.getString("id")),rs.getLong("owner_id"),rs.getString("operation_type"),UUID.fromString(rs.getString("task_instance_id")),rs.getString("status"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant());}
 private ProgressView progressView(long ownerId,UUID itemId){return jdbc.query("SELECT * FROM playback_progress WHERE owner_id=? AND media_item_id=?",(rs,row)->new ProgressView(rs.getLong("owner_id"),UUID.fromString(rs.getString("media_item_id")),rs.getLong("position_ms"),rs.getLong("duration_ms"),rs.getBoolean("completed"),rs.getLong("revision"),rs.getTimestamp("client_updated_at").toInstant(),rs.getTimestamp("server_updated_at").toInstant()),ownerId,itemId.toString()).getFirst();}
 private List<String> tags(UUID id){return jdbc.query("SELECT t.name FROM media_tag t JOIN media_tag_relation r ON r.tag_id=t.id WHERE r.media_item_id=? ORDER BY t.name",(rs,row)->rs.getString(1),id.toString());}
 private AnalysisView analysis(java.sql.ResultSet rs)throws java.sql.SQLException{return new AnalysisView(UUID.fromString(rs.getString("id")),UUID.fromString(rs.getString("media_item_id")),rs.getString("analysis_version"),UUID.fromString(rs.getString("task_instance_id")),rs.getString("status"));}
 private ItemRecord item(java.sql.ResultSet rs)throws java.sql.SQLException{return new ItemRecord(UUID.fromString(rs.getString("id")),rs.getLong("owner_id"),UUID.fromString(rs.getString("asset_id")),rs.getString("source_type"),rs.getString("source_business_id"),rs.getString("content_sha256"),rs.getLong("size_bytes"),rs.getString("mime_type"),rs.getString("status"),rs.getLong("version"));}
 private List<String> analysisRelations(UUID id){return jdbc.query("SELECT analysis_version,status,result_sha256,error_code FROM media_analysis WHERE media_item_id=? ORDER BY analysis_version",(rs,row)->String.join("|",rs.getString(1),rs.getString(2),Objects.toString(rs.getString(3),""),Objects.toString(rs.getString(4),"")),id.toString());}
 private List<String> tagRelations(UUID id){return jdbc.query("SELECT t.name,r.source,r.confidence,r.analysis_version FROM media_tag_relation r JOIN media_tag t ON t.id=r.tag_id WHERE r.media_item_id=? ORDER BY t.name,r.source",(rs,row)->String.join("|",rs.getString(1),rs.getString(2),Objects.toString(rs.getBigDecimal(3),""),Objects.toString(rs.getString(4),"")),id.toString());}
 private List<String> artifactRelations(UUID id){return jdbc.query("SELECT artifact_kind,generator_version,asset_id FROM media_artifact WHERE media_item_id=? ORDER BY artifact_kind,generator_version",(rs,row)->String.join("|",rs.getString(1),rs.getString(2),rs.getString(3)),id.toString());}
 private List<String> directoryRelations(UUID id){return jdbc.query("SELECT d.external_key,e.source_business_id,e.status,e.last_seen_scan_id FROM media_directory_entry e JOIN media_directory d ON d.id=e.directory_id WHERE e.media_item_id=? ORDER BY d.external_key,e.source_business_id",(rs,row)->String.join("|",rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4)),id.toString());}
 private List<String> sourceRelations(UUID id){return jdbc.query("SELECT owner_id,source_type,source_business_id,display_name FROM media_item_source WHERE media_item_id=? ORDER BY owner_id,source_type,source_business_id",(rs,row)->String.join("|",Long.toString(rs.getLong(1)),rs.getString(2),rs.getString(3),rs.getString(4)),id.toString());}
 private List<String> sourceTagRelations(UUID id){return jdbc.query("SELECT s.owner_id,s.source_type,s.source_business_id,t.name,s.confidence FROM media_item_source_tag s JOIN media_tag t ON t.id=s.tag_id WHERE s.media_item_id=? ORDER BY s.owner_id,s.source_type,s.source_business_id,t.name",(rs,row)->String.join("|",Long.toString(rs.getLong(1)),rs.getString(2),rs.getString(3),rs.getString(4),Objects.toString(rs.getBigDecimal(5),"")),id.toString());}
 private void bumpRevision(Instant now){jdbc.update("UPDATE media_library_revision SET revision=revision+1,updated_at=? WHERE singleton_id=1",Timestamp.from(now));}
 private record AnalysisRecord(UUID id,String version,String status,String resultHash){}
 private record TerminalRecord(String status,String errorCode){}
 private record QueryParts(String from,String where,List<Object>arguments){}
 /** 对账媒体主记录。 */ public record ItemRecord(UUID id,long ownerId,UUID assetId,String sourceType,String sourceBusinessId,String contentSha256,long sizeBytes,String mimeType,String status,long version){}
 /** 对账媒体关系快照。 */ public record ReconciliationSnapshot(ItemRecord item,List<String> analyses,List<String> tags,List<String> artifacts,List<String> directories,List<String> sources,List<String> sourceTags){}
 /** 旧媒体迁移审计记录。 */ public record LegacyMigrationRecord(String migrationKey,String sourceSnapshotId,String sourceSystem,String legacyAssetId,String payloadSha256,UUID mediaItemId,int tagCount){}
}
